from h import *
O=[]
O.append(R(6523505,
es=("Ensalada de pepino y rábano","¿Le encantan los sabores de las verduras frescas? ¡Pruebe esta ensalada de pepino y rábano! Acompañada de hierbas frescas y un aderezo sencillo, es un excelente aperitivo o guarnición para cualquier comida que necesite un toque más de color.","6","1 taza",
["2 pepinos medianos (en rodajas finas)","1 taza de rábanos (en rodajas finas)","1/4 de taza de cebolla morada (en rodajas finas)","2 cucharadas de eneldo fresco (picado)","2 cucharadas de perejil fresco (picado)","2 cucharadas de vinagre de vino blanco","2 cucharadas de aceite de oliva","1/2 cucharadita de sal kosher","1/4 de cucharadita de pimienta negra"],
["En un tazón grande, mezcle los pepinos en rodajas finas, los rábanos, la cebolla morada, el eneldo fresco picado y el perejil fresco.","En un tazón pequeño, bata el vinagre de vino blanco, el aceite de oliva, la sal y la pimienta.","Vierta el aderezo sobre la mezcla de pepino, rábano y hierbas.","Mezcle la ensalada con suavidad para que quede cubierta de manera uniforme.","Deje marinar la ensalada en el refrigerador durante al menos 15 minutos para intensificar los sabores."],[],[]),
ar=("سلطة الخيار والفجل","هل تحب نكهات الخضار الطازجة؟ إذن جرّب سلطة الخيار والفجل هذه! مع الأعشاب الطازجة وصلصة السلطة السهلة، تصلح مقبلات أو سلطة جانبية رائعة لأي وجبة تحتاج إلى مزيد من الألوان.","6","1 كوب",
["2 خيارة متوسطة (مقطعة إلى شرائح رفيعة)","1 كوب فجل (مقطع إلى شرائح رفيعة)","¼ كوب بصل أحمر (مقطع إلى شرائح رفيعة)","2 ملعقة كبيرة شبت طازج (مفروم)","2 ملعقة كبيرة بقدونس طازج (مفروم)","2 ملعقة كبيرة خل النبيذ الأبيض","2 ملعقة كبيرة زيت زيتون","½ ملعقة صغيرة ملح كوشر","¼ ملعقة صغيرة فلفل أسود"],
["في وعاء كبير، اخلط الخيار المقطع إلى شرائح رفيعة والفجل والبصل الأحمر والشبت الطازج المفروم والبقدونس الطازج.","في وعاء صغير، اخفق خل النبيذ الأبيض وزيت الزيتون والملح والفلفل.","اسكب الصلصة فوق خليط الخيار والفجل والأعشاب.","قلّب السلطة برفق حتى تتغطى بالتساوي.","اترك السلطة تتتبّل في الثلاجة لمدة 15 دقيقة على الأقل لتعزيز النكهات."],[],[])))
O.append(R(6523847,
ar=("سندويشات بيتا بالسلطة اليونانية والروبيان المشوي اقتصادية","قدّم هذا الطبق مع كوب من شوربة الغازباتشو الباردة أو مع كوسا مسوّطة متبّلة بعصير الليمون والأوريغانو.","4","½ رغيف بيتا + 4 روبيان + ¾ كوب سلطة",
["2 كوب خس روماني (مقطع شرائح)","½ بصلة حمراء صغيرة (مقطعة إلى شرائح رفيعة)","½ خيارة كبيرة، أو خيارة صغيرة واحدة (مقشرة ومقطعة إلى شرائح)","⅓ كوب جبن فيتا (قليل الدسم، مفتت)","1 ملعقة كبيرة زيت زيتون","2 ملعقة كبيرة خل النبيذ الأحمر","1 ملعقة كبيرة أوريغانو طازج (مفروم)","2 رغيف بيتا متوسط من القمح الكامل (مقطع إلى نصفين)","12 روبيان متوسط (مقشر ومنزوع الأمعاء)","1 ملعقة صغيرة ملح (اختياري)","1 ملعقة صغيرة فلفل أسود","¼ ملعقة صغيرة فلفل كايين","1 بخّة (0.25 غرام) بخاخ طهي غير لاصق"],
["جهّز شواية داخلية أو خارجية.","في وعاء كبير، اخلط الخس والبصل والخيار وجبن الفيتا وزيت الزيتون وخل النبيذ الأحمر والأوريغانو.","املأ كل نصف من جيب البيتا بربع خليط الخس. ضعه جانبًا.","تبّل الروبيان بالملح (اختياري) والفلفل الأسود المطحون وفلفل الكايين. رشّ الروبيان ببخاخ الطهي.","اشوِ الروبيان لمدة 3-4 دقائق على كل جانب. ارفعه عن الشواية وضع 3 روبيان في كل رغيف بيتا."],[],[])))
O.append(R(6523980,
ar=("شوربة حصاد الحديقة","عدّل الخضار في هذه الشوربة بحسب ما لديك في الثلاجة. كن مبدعًا في اختيار تشكيلة الخضار التي تستخدمها!","2","1¼ كوب",
["1 ملعقة صغيرة زيت زيتون","2 كوب خضار (نيئة ومقطعة، مثل أي تشكيلة من الفلفل الرومي والجزر والفاصولياء الخضراء والقرع الأصفر الصيفي أو الكوسا)","¼ كوب بصل (مفروم ناعمًا)","1 ملعقة صغيرة خليط توابل إيطالية (مفتتة)","2 كوب مرق دجاج قليل الصوديوم (أو مرق خضار قليل الصوديوم أو خالٍ من الدهون وقليل الصوديوم)","1 كوب أوراق سبانخ طازجة (غير مكبوسة، مفرومة فرمًا خشنًا)","1 ملعقة كبيرة جبن بارميزان (مبشور)"],
["في قدر متوسط، سخّن الزيت على نار متوسطة مع تحريك القدر ليغطي القاع. اطهِ الكوبين من الخضار المقطعة والبصل وخليط التوابل لمدة 8 إلى 10 دقائق، أو حتى تصبح طرية ومقرمشة قليلًا، مع التحريك من حين لآخر. (إذا جفّت الخضار أو بدأت تحترق، فأضف قليلًا من الماء إلى القدر.)","أضف المرق وقلّب. ارفع الحرارة إلى متوسطة عالية واتركه حتى يغلي. اخفض الحرارة واتركه على نار هادئة لمدة 15 دقيقة لتمتزج النكهات، مع التحريك من حين لآخر. أضف السبانخ وقلّب. رشّ كل حصة بجبن البارميزان.","نصائح: قطّع الخضار الأكثر صلابة، مثل الجزر، إلى قطع أصغر من الخضار الأكثر طراوة، مثل الكوسا، لكي تنضج جميع الخضار بالسرعة نفسها تقريبًا. وإذا أردت أن يكون هذا الطبق نباتيًا، فاحرص على استخدام مرق الخضار بدلًا من مرق الدجاج."],[],[])))
O.append(R(6525164,
es=("Pan de jengibre fresco integral","Este pan de jengibre fresco es una versión saludable de un clásico favorito: ofrece las notas cálidas y especiadas del jengibre y la melaza, pero con los beneficios de la harina integral. ¡Es un complemento delicioso para su mesa navideña que seguramente toda la familia disfrutará! Esta receta apta para personas con diabetes es una gran opción para llevar a un intercambio de galletas navideñas o para servir en su comida de fiestas y celebrar la temporada.","12","1 rebanada",
["2 tazas de harina de trigo integral","1/3 de taza de sustituto de azúcar morena","1 cucharadita de bicarbonato de sodio","1/2 cucharadita de polvo de hornear","1/2 cucharadita de sal","1 cucharadita de canela molida","1 cucharadita de jengibre molido","1/2 cucharadita de nuez moscada molida","1/4 de cucharadita de clavo molido","1/2 taza de compota de manzana sin azúcar","1/3 de taza de miel de maple","1/4 de taza de aceite vegetal","2 cucharadas de jengibre fresco (rallado)","2 huevos grandes","1 cucharadita de extracto de vainilla","1 taza de agua (caliente)"],
["Precaliente el horno a 350 grados F. Engrase un molde para pan de 9x5 pulgadas.","En un tazón grande, bata la harina integral, el sustituto de azúcar morena, el bicarbonato de sodio, el polvo de hornear, la sal, la canela, el jengibre, la nuez moscada y el clavo.","En otro tazón, mezcle la compota de manzana, la miel de maple, el aceite vegetal, el jengibre recién rallado, los huevos y el extracto de vainilla. Mezcle hasta que todo esté bien integrado.","Agregue poco a poco los ingredientes líquidos a los ingredientes secos, revolviendo solo hasta que se integren. No mezcle en exceso.","Vierta lentamente el agua caliente mientras revuelve la masa con suavidad. La masa quedará líquida.","Vierta la masa en el molde para pan preparado.","Hornee en el horno precalentado durante unos 45 a 50 minutos, o hasta que un palillo insertado en el centro del pan salga limpio.","Cuando esté horneado, saque el pan de jengibre del horno y déjelo enfriar en el molde durante unos 10 minutos. Luego, retírelo con cuidado del molde y páselo a una rejilla para que se enfríe por completo."],[],[]),
ar=("خبز الزنجبيل الطازج بالقمح الكامل","رغيف خبز الزنجبيل الطازج هذا هو نسخة صحية من وصفة كلاسيكية محبوبة، فهو يمنحك النكهات الدافئة المتبّلة للزنجبيل والدبس، مع فوائد دقيق القمح الكامل. إنه إضافة رائعة إلى مائدة العطلة ستعجب العائلة كلها بالتأكيد! وهذه الوصفة المناسبة لمرضى السكري خيار رائع لتحضيرها إلى تبادل بسكويت العطلات أو لتقديمها في وجبة العطلة احتفالًا بالموسم.","12","1 شريحة",
["2 كوب دقيق القمح الكامل","⅓ كوب بديل السكر البني","1 ملعقة صغيرة بيكربونات الصوديوم","½ ملعقة صغيرة بيكنغ باودر","½ ملعقة صغيرة ملح","1 ملعقة صغيرة قرفة مطحونة","1 ملعقة صغيرة زنجبيل مطحون","½ ملعقة صغيرة جوزة الطيب المطحونة","¼ ملعقة صغيرة قرنفل مطحون","½ كوب صلصة تفاح غير محلاة","⅓ كوب شراب القيقب","¼ كوب زيت نباتي","2 ملعقة كبيرة زنجبيل طازج (مبشور)","2 بيضة كبيرة","1 ملعقة صغيرة خلاصة الفانيلا","1 كوب ماء (ساخن)"],
["سخّن الفرن مسبقًا إلى 350 درجة فهرنهايت (175 درجة مئوية). ادهن قالب خبز مقاس 9×5 بوصات.","في وعاء كبير، اخفق دقيق القمح الكامل وبديل السكر البني وبيكربونات الصوديوم والبيكنغ باودر والملح والقرفة والزنجبيل وجوزة الطيب والقرنفل.","في وعاء آخر، اخلط صلصة التفاح وشراب القيقب والزيت النباتي والزنجبيل المبشور طازجًا والبيض وخلاصة الفانيلا. اخلط حتى تتجانس المكونات جيدًا.","أضف المكونات السائلة تدريجيًا إلى المكونات الجافة مع التقليب حتى تمتزج فقط. لا تفرط في الخلط.","اسكب الماء الساخن ببطء مع تقليب العجينة برفق. ستكون العجينة سائلة.","اسكب العجينة في قالب الخبز المجهّز.","اخبز في الفرن المسخّن مسبقًا لمدة 45-50 دقيقة تقريبًا، أو حتى تخرج عود الأسنان نظيفًا عند غرزه في وسط الخبز.","بعد الخَبز، أخرج خبز الزنجبيل من الفرن واتركه يبرد في القالب لمدة 10 دقائق تقريبًا. ثم أخرجه من القالب بعناية وانقله إلى رف شبكي ليبرد تمامًا."],[],[])))
O.append(R(6525410,
es=("Sopa fría de pepino y sándwich abierto de camarones a la parrilla","Fresca como un pepino, esta sopa refrescante combina de maravilla con un sándwich abierto de camarones a la parrilla y alioli de aguacate picante. Si el picante es demasiado, puede omitir la salsa picante o usar solo una pizca.","4","1¼ tazas de sopa + 1 sándwich abierto",
["2 pepinos medianos (cortados en tercios y por la mitad a lo largo)","2 tazas de yogur griego natural sin grasa","4 cucharadas de jugo de limón (de 2 limones medianos, divididas)","1 cucharada de ralladura de limón","1 cucharada de eneldo fresco","1 rociada de aceite en aerosol antiadherente de 0.25 g","8 oz de camarones (pelados y desvenados)","1 cucharada de aceite de oliva extra virgen","1/4 de cucharadita de pimienta negra","4 cucharadas de mayonesa light","1/2 aguacate mediano","1/8 de cucharadita de salsa picante","1 taza de arúgula","4 rebanadas de pan integral (tostadas)"],
["Para preparar la sopa, coloque la mitad de los pepinos en un procesador de alimentos con la cuchilla para picar. Procese hasta que queden en trozos pequeños. Agregue los trozos de pepino restantes y procese hasta que queden en trozos pequeños.","Agregue el yogur, el jugo de limón, la ralladura de limón y el eneldo, y procese hasta que se licúe y todos los trozos de pepino estén hechos puré.","Rocíe una sartén de parrilla o una parrilla al aire libre con el aceite en aerosol y caliéntela a fuego medio. Mezcle los camarones con el aceite de oliva y la pimienta negra. Colóquelos en la parrilla precalentada y cocínelos durante 1 minuto. Voltee los camarones y cocínelos 1 minuto más. Los camarones se cocinan rápido, así que tenga cuidado de no cocinarlos demasiado. Retírelos de la parrilla y páselos a un plato.","En un tazón pequeño, aplaste el aguacate y agregue la mayonesa, el jugo de limón y la salsa picante; mezcle hasta que tenga un color verde claro y el aguacate esté bien integrado y sin grumos.","Unte 1 cucharada del alioli de aguacate sobre cada rebanada de pan tostado. Coloque encima 1/4 de taza de arúgula y 3 camarones. Sirva con 1¼ tazas de la sopa a un lado."],[],[]),
ar=("شوربة الخيار الباردة وسندويش الروبيان المشوي المفتوح","منعشة كالخيار، تتناسب هذه الشوربة المنعشة تمامًا مع سندويش مفتوح من الروبيان المشوي وأيولي الأفوكادو الحار. وإذا كانت الحرارة زائدة، فيمكنك الاستغناء عن الصلصة الحارة أو استخدام رشة صغيرة فقط.","4","1¼ كوب شوربة + 1 سندويش مفتوح",
["2 خيارة متوسطة (مقطعة إلى ثلاثة أجزاء ثم إلى نصفين بالطول)","2 كوب زبادي يوناني سادة خالٍ من الدسم","4 ملعقة كبيرة عصير ليمون (من 2 ليمونة متوسطة، مقسّمة)","1 ملعقة كبيرة قشر ليمون مبشور","1 ملعقة كبيرة شبت طازج","1 بخّة (0.25 غرام) بخاخ طهي غير لاصق","8 أونصة روبيان (مقشر ومنزوع الأمعاء)","1 ملعقة كبيرة زيت زيتون بكر ممتاز","¼ ملعقة صغيرة فلفل أسود","4 ملعقة كبيرة مايونيز خفيف","½ حبة أفوكادو متوسطة","⅛ ملعقة صغيرة صلصة حارة","1 كوب جرجير","4 شرائح خبز حبوب كاملة (محمصة)"],
["لتحضير الشوربة، ضع نصف الخيار في محضّرة الطعام المزوّدة بشفرة التقطيع. شغّلها حتى يتقطع الخيار إلى قطع صغيرة. أضف أجزاء الخيار المتبقية وشغّلها حتى تتقطع إلى قطع صغيرة.","أضف الزبادي وعصير الليمون وقشر الليمون والشبت وشغّل المحضّرة حتى يصبح الخليط سائلًا وتتحول كل قطع الخيار إلى هريس.","رشّ مقلاة شواء أو شواية خارجية ببخاخ الطهي وسخّنها على حرارة متوسطة. قلّب الروبيان مع زيت الزيتون والفلفل الأسود. ضعه على الشواية المسخّنة مسبقًا واتركه لمدة دقيقة واحدة. اقلب الروبيان واتركه دقيقة إضافية. ينضج الروبيان بسرعة، لذا احرص على ألا تفرط في طهيه. ارفعه عن الشواية إلى طبق.","في وعاء صغير، اهرس الأفوكادو وأضف المايونيز وعصير الليمون والصلصة الحارة، ثم اخلط حتى يصبح لونه أخضر فاتحًا ويمتزج الأفوكادو تمامًا ويصبح الخليط ناعمًا.","ادهن 1 ملعقة كبيرة من أيولي الأفوكادو على كل شريحة خبز محمص. ضع فوقها ¼ كوب من الجرجير و3 روبيان. قدّمها مع 1¼ كوب من الشوربة بجانبها."],[],[])))
O.append(R(6526217,
es=("Fajitas de tofu en bandeja para hornear","Las cenas en una sola bandeja son una forma rápida y fácil de disfrutar de una comida nutritiva sin tener que limpiar mucho. Estas fajitas de tofu aptas para personas con diabetes son una comida que le encantará a toda la familia y usan proteína de origen vegetal para mantenerlo satisfecho por más tiempo.","4","1 tortilla + 1/4 del relleno",
["16 oz de tofu extrafirme (prensado y cortado en cubos)","1 pimiento morrón rojo mediano (en tiras)","1 pimiento morrón amarillo mediano (en tiras)","1 cebolla morada mediana (en rodajas finas)","1 cucharada de aceite de oliva","2 cucharadas de condimento para tacos bajo en sodio","1 cucharadita de comino molido","1 cucharadita de pimentón ahumado","1/2 cucharadita de chile en polvo","1/2 cucharadita de pimienta negra","4 tortillas tipo burrito de trigo integral bajas en carbohidratos","2 cucharadas de cilantro fresco (picado)","1 lima entera (cortada en gajos)"],
["Precaliente el horno a 400 grados F. Cubra una bandeja para hornear con papel pergamino.","Presione el tofu para eliminar el exceso de agua y luego córtelo en cubos.","En un tazón grande, mezcle los cubos de tofu, los pimientos en tiras y la cebolla morada en rodajas.","En un tazón pequeño, bata el aceite de oliva, el condimento para tacos, el comino molido, el pimentón ahumado, el chile en polvo y la pimienta negra para preparar la marinada.","Vierta la marinada sobre el tofu y las verduras. Mezcle hasta que todo quede cubierto de manera uniforme. Deje marinar durante al menos 30 minutos.","Extienda el tofu marinado y las verduras de manera uniforme sobre la bandeja.","Hornee en el horno precalentado durante 25 minutos o hasta que el tofu esté dorado y las verduras estén tiernas, revolviendo a la mitad del tiempo.","Divida el relleno de las fajitas entre las tortillas.","Sirva las fajitas de tofu en bandeja y decore con el cilantro picado y los gajos de lima."],[],[]),
ar=("فاهيتا التوفو على صينية الفرن","وجبات العشاء على صينية واحدة طريقة سريعة وسهلة للاستمتاع بوجبة مغذية دون الكثير من التنظيف. وجبة فاهيتا التوفو هذه المناسبة لمرضى السكري ستعجب العائلة كلها، وتعتمد على بروتين نباتي يمنحك الشبع والرضا.","4","1 رغيف تورتيلا + ¼ الحشوة",
["16 أونصة توفو شديد الصلابة (مضغوط ومقطع إلى مكعبات)","1 حبة فلفل رومي أحمر متوسطة (مقطعة إلى شرائح)","1 حبة فلفل رومي أصفر متوسطة (مقطعة إلى شرائح)","1 حبة بصل أحمر متوسطة (مقطعة إلى شرائح رفيعة)","1 ملعقة كبيرة زيت زيتون","2 ملعقة كبيرة بهارات التاكو قليلة الصوديوم","1 ملعقة صغيرة كمون مطحون","1 ملعقة صغيرة بابريكا مدخنة","½ ملعقة صغيرة مسحوق الفلفل الحار","½ ملعقة صغيرة فلفل أسود","4 أرغفة بوريتو من القمح الكامل قليلة الكربوهيدرات","2 ملعقة كبيرة كزبرة خضراء طازجة (مفرومة)","1 حبة ليمون أخضر كاملة (مقطعة إلى أرباع)"],
["سخّن الفرن مسبقًا إلى 400 درجة فهرنهايت (200 درجة مئوية). بطّن صينية الفرن بورق الزبدة.","اضغط التوفو للتخلص من الماء الزائد، ثم قطّعه إلى مكعبات.","في وعاء كبير، اخلط مكعبات التوفو وشرائح الفلفل الرومي وشرائح البصل الأحمر.","في وعاء صغير، اخفق زيت الزيتون وبهارات التاكو والكمون المطحون والبابريكا المدخنة ومسحوق الفلفل الحار والفلفل الأسود لتحضير التتبيلة.","اسكب التتبيلة فوق التوفو والخضار. قلّب حتى يتغطى كل شيء بالتساوي. اتركه ليتتبّل لمدة 30 دقيقة على الأقل.","وزّع التوفو المتبّل والخضار بالتساوي على الصينية.","حمّص في الفرن المسخّن مسبقًا لمدة 25 دقيقة أو حتى يصبح التوفو ذهبي اللون والخضار طرية، مع التقليب في منتصف المدة.","قسّم حشوة الفاهيتا على الأرغفة.","قدّم فاهيتا التوفو وزيّنها بالكزبرة الخضراء المفرومة وأرباع الليمون الأخضر."],[],[])))
O.append(R(6526998,
ar=("سلطة الغازباتشو من بوفيه السلطات","تعتمد هذه السلطة اللذيذة على صلصة خفيفة أساسها الطماطم، وهي مليئة بالخضروات الورقية وغيرها من الخضار الغنية بالعناصر الغذائية. اشترِ أكبر قدر ممكن من هذه الخضار مقطعة مسبقًا من بوفيه السلطات في المتجر لتوفير وقت التحضير.","5","2 كوب",
["2 كوب حمص أو فاصولياء حمراء أو فاصولياء سوداء (من بوفيه السلطات أو معلبة، مصفاة ومشطوفة)","1½ كوب طماطم (مقطعة إلى مكعبات)","⅔ كوب ذرة","⅔ كوب خيار (مقطع إلى مكعبات)","3 ملعقة كبيرة بصل أحمر (مقطع إلى مكعبات)","2 ملعقة كبيرة كزبرة خضراء (مفرومة ناعمًا)","¼ كوب عصير طماطم (قليل الصوديوم)","2 ملعقة كبيرة عصير ليمون أخضر طازج","1 ملعقة كبيرة زيت زيتون","½ ملعقة صغيرة مسحوق الفلفل الحار (خفيف أو حار)","¼ ملعقة صغيرة ملح كوشر","¼ ملعقة صغيرة فلفل أسود مطحون طازجًا","5 كوب خضروات ورقية مشكلة"],
["اخلط الفاصولياء والطماطم والذرة والخيار والبصل الأحمر والكزبرة الخضراء.","في وعاء صغير، اخفق عصير الطماطم وعصير الليمون الأخضر وزيت الزيتون ومسحوق الفلفل الحار والملح والفلفل. اسكبه فوق السلطة واخلط برفق. قدّمها فوق الخضروات الورقية المشكلة."],[],[])))
O.append(R(6527440,
es=("Ensalada de camote","¿Quién dice que solo se pueden usar papas blancas para una ensalada de papa? Este plato será una sorpresa bienvenida en su próximo picnic de verano.","12","1/2 taza",
["3 camotes grandes (de unas 13 onzas cada uno)","4 rebanadas de tocino de pavo","2 cucharadas de aceite de oliva","1 cucharada de vinagre de sidra de manzana","1/8 de cucharadita de pimienta negra","1/2 cucharadita de ajo en polvo","3 tallos de apio (en cubos)","2 tallos de cebolleta (en rodajas)"],
["Pele los camotes y córtelos en cubos. Colóquelos en una olla grande. Cúbralos con agua y hierva. Hierva hasta que estén tiernos, unos 5 a 7 minutos. Escurra los camotes y enjuáguelos con agua fría; déjelos enfriar.","Mientras se cocinan los camotes, cocine el tocino hasta que esté crujiente y luego pique o desmenuce en trozos pequeños.","En un tazón pequeño, bata el aceite de oliva, el vinagre de sidra de manzana, la pimienta y el ajo en polvo.","Coloque los camotes en un tazón para servir y agregue el apio, la cebolleta y el tocino de pavo. Vierta el aderezo sobre la ensalada y mezcle hasta que los camotes queden cubiertos. Sirva fría."],[],[]),
ar=("سلطة البطاطا الحلوة","من قال إنه لا يمكن استخدام البطاطس البيضاء فقط في سلطة البطاطس؟ سيكون هذا الطبق مفاجأة مرحَّبًا بها في نزهتك الصيفية القادمة.","12","½ كوب",
["3 حبات بطاطا حلوة كبيرة (حوالي 13 أونصة لكل حبة)","4 شرائح بيكون ديك رومي","2 ملعقة كبيرة زيت زيتون","1 ملعقة كبيرة خل التفاح","⅛ ملعقة صغيرة فلفل أسود","½ ملعقة صغيرة مسحوق الثوم","3 سيقان كرفس (مقطعة إلى مكعبات)","2 ساق بصل أخضر (مقطعة إلى شرائح)"],
["قشّر البطاطا الحلوة وقطّعها إلى مكعبات. ضعها في قدر كبير. غطِّها بالماء واتركها حتى تغلي. اسلقها حتى تصبح طرية، حوالي 5-7 دقائق. صفِّ البطاطا واشطفها بالماء البارد، ثم اتركها لتبرد.","أثناء طهي البطاطا، اطهِ البيكون حتى يصبح مقرمشًا، ثم قطّعه أو فتّته إلى قطع صغيرة.","في وعاء صغير، اخفق زيت الزيتون وخل التفاح والفلفل ومسحوق الثوم.","ضع البطاطا الحلوة في وعاء التقديم وأضف الكرفس والبصل الأخضر وبيكون الديك الرومي. اسكب الصلصة فوق السلطة وقلّب حتى تتغطى البطاطا. قدّمها باردة."],[],[])))
O.append(R(6527594,
es=("Ensalada de mango con pollo","¡La ensalada de pollo tradicional se vuelve un poco más animada con el mango! Encuentre esta receta y más en The New Soul Food Cookbook for People with Diabetes.","6","1 taza de ensalada de pollo + 3 hojas de lechuga",
["1/3 de taza de mayonesa light","3 tallos de cebolleta (picados)","2 tazas de pechuga de pollo cocida (en cubos)","2 tazas de mango (picado)","1 pimiento morrón verde mediano (sin semillas y picado)","1 cucharada de vinagre de sidra de manzana","2 cucharadas de jugo de limón","1 cucharadita de azúcar","18 hojas de lechuga romana"],
["Mezcle la mayonesa y la cebolleta en un tazón pequeño, tape y refrigere. Mezcle el pollo, el mango y el pimiento en un tazón grande.","Combine el vinagre, el jugo de limón y el azúcar en un recipiente con tapa hermética. Agite bien. Agregue la mezcla de limón a la mezcla de mayonesa y cebolleta y revuelva bien.","Vierta el aderezo sobre el pollo y el mango, mezcle bien y refrigere durante 30 minutos. Para servir, coloque con una cuchara sobre un plato forrado con hojas de lechuga."],[],[]),
ar=("سلطة المانجو مع الدجاج","سلطة الدجاج التقليدية تصبح أكثر حيوية قليلًا بإضافة المانجو! ستجد هذه الوصفة وغيرها في كتاب The New Soul Food Cookbook for People with Diabetes.","6","1 كوب سلطة دجاج + 3 أوراق خس",
["⅓ كوب مايونيز خفيف","3 ساق بصل أخضر (مفرومة)","2 كوب صدر دجاج مطبوخ (مقطع إلى مكعبات)","2 كوب مانجو (مقطعة)","1 حبة فلفل رومي أخضر متوسطة (منزوعة البذور ومقطعة)","1 ملعقة كبيرة خل التفاح","2 ملعقة كبيرة عصير ليمون","1 ملعقة صغيرة سكر","18 ورقة خس روماني"],
["اخلط المايونيز والبصل الأخضر في وعاء صغير، وغطِّه وضعه في الثلاجة. اخلط الدجاج والمانجو والفلفل الرومي في وعاء كبير.","اخلط الخل وعصير الليمون والسكر في وعاء محكم الغطاء. رجَّه جيدًا. أضف خليط الليمون إلى خليط المايونيز والبصل الأخضر وقلّب جيدًا.","اسكب الصلصة فوق الدجاج والمانجو وقلّب جيدًا وضعه في الثلاجة لمدة 30 دقيقة. عند التقديم، اغرف السلطة في طبق مبطّن بأوراق الخس."],[],[])))
O.append(R(6529405,
es=("Bol de tacos con papas crujientes","Este bol de tacos tiene una base abundante de papas blancas asadas y arroz de coliflor esponjoso, cubierto con carne molida sazonada, champiñones y pimientos morrones rojos. El jugo de lima fresco y el cilantro realzan cada bocado, mientras que el aguacate cremoso aporta riqueza y equilibrio. Es una versión satisfactoria, llena de verduras y alta en fibra de los sabores clásicos del taco, lo bastante fácil para las noches entre semana y perfecta para armar su propio bol.","4","1 bol (unas 2 1/2 tazas)",
["12 oz de papas blancas (unas 2 medianas, cortadas en cubos de 1/2 pulgada)","1 cucharada de aceite de oliva (dividida)","1/2 cucharadita de sal kosher","1/4 de cucharadita de pimienta negra","8 oz de carne molida de res extra magra al 4 %","8 oz de champiñones (picados finos)","1 taza de pimiento morrón rojo (aproximadamente 1 pimiento mediano, en cubos)","1 cucharadita de chile en polvo","1 cucharadita de comino molido","1/2 cucharadita de pimentón ahumado","1/4 de cucharadita de ajo en polvo","1/4 de cucharadita de cebolla en polvo","1/2 taza de salsa de tomate sin sal agregada","1/4 de taza de agua","2 tazas de arroz de coliflor","2 cucharadas de jugo de lima fresco (aproximadamente 1 lima)","1/4 de taza de cilantro fresco (picado)","8 tomates cherry enteros (cortados a la mitad)","1 aguacate mediano (en rodajas)"],
["Precaliente el horno a 425 grados F. Mezcle las papas en cubos con 1 1/2 cucharaditas de aceite de oliva, 1/4 de cucharadita de sal y 1/8 de cucharadita de pimienta negra. Extiéndalas en una sola capa sobre una bandeja para hornear y áselas durante 20 a 25 minutos, revolviendo una vez a la mitad del tiempo, hasta que estén tiernas y ligeramente doradas.","En la misma sartén, caliente a fuego medio el resto de las 1 1/2 cucharaditas de aceite de oliva. Agregue la carne molida, los champiñones picados y el pimiento morrón rojo en cubos. Cocine de 8 a 10 minutos, desmenuzando la carne, hasta que esté completamente cocida y las verduras estén tiernas.","Agregue el chile en polvo, el comino, el pimentón ahumado, el ajo en polvo, la cebolla en polvo, el resto de 1/4 de cucharadita de sal y 1/4 de cucharadita de pimienta negra. Cocine de 1 a 2 minutos hasta que desprenda aroma. Agregue la salsa de tomate y el agua, y deje que hierva a fuego lento. Deje que hierva y luego reduzca el fuego y cocine a fuego lento de 5 a 7 minutos, hasta que el líquido se reduzca. Retire del fuego.","Mientras la mezcla de carne hierve a fuego lento, caliente el arroz de coliflor en una sartén antiadherente grande a fuego medio de 3 a 4 minutos, revolviendo de vez en cuando, hasta que esté caliente por completo. Agregue el cilantro y el jugo de lima y mezcle. Manténgalo caliente hasta el momento de servir.","Divida el arroz de coliflor en partes iguales entre cuatro bols. Cubra cada bol de manera uniforme con las papas asadas, la mezcla de carne, champiñones y pimiento, dos tomates y 1/4 de aguacate en rodajas."],[],[]),
ar=("وعاء التاكو بالبطاطس المقرمشة","يتميز وعاء التاكو هذا بقاعدة غنية من البطاطس البيضاء المحمصة وأرز القرنبيط الهش، يعلوها لحم البقر المفروم اللذيذ والفطر والفلفل الرومي الأحمر. يضفي عصير الليمون الأخضر الطازج والكزبرة الخضراء نكهة مميزة على كل لقمة، بينما يضيف الأفوكادو الكريمي غنى وتوازنًا. إنه نسخة مشبعة ومليئة بالخضار وغنية بالألياف من نكهات التاكو الكلاسيكية، سهلة بما يكفي لليالي الأسبوع ومثالية للأوعية التي تُعدّها بنفسك.","4","1 وعاء (حوالي 2½ كوب)",
["12 أونصة بطاطس بيضاء (حوالي حبتين متوسطتين، مقطعة إلى مكعبات بحجم ½ بوصة)","1 ملعقة كبيرة زيت زيتون (مقسّمة)","½ ملعقة صغيرة ملح كوشر","¼ ملعقة صغيرة فلفل أسود","8 أونصة لحم بقر مفروم قليل الدسم جدًا 4%","8 أونصة فطر (مفروم ناعمًا)","1 كوب فلفل رومي أحمر (حوالي حبة متوسطة، مقطعة إلى مكعبات)","1 ملعقة صغيرة مسحوق الفلفل الحار","1 ملعقة صغيرة كمون مطحون","½ ملعقة صغيرة بابريكا مدخنة","¼ ملعقة صغيرة مسحوق الثوم","¼ ملعقة صغيرة مسحوق البصل","½ كوب صلصة طماطم بدون ملح مضاف","¼ كوب ماء","2 كوب أرز القرنبيط","2 ملعقة كبيرة عصير ليمون أخضر طازج (حوالي ليمونة واحدة)","¼ كوب كزبرة خضراء طازجة (مفرومة)","8 حبات طماطم كرزية (مقطعة إلى نصفين)","1 حبة أفوكادو متوسطة (مقطعة إلى شرائح)"],
["سخّن الفرن مسبقًا إلى 425 درجة فهرنهايت (220 درجة مئوية). قلّب مكعبات البطاطس مع 1½ ملعقة صغيرة من زيت الزيتون و¼ ملعقة صغيرة من الملح و⅛ ملعقة صغيرة من الفلفل الأسود. افردها في طبقة واحدة على صينية خبز وحمّصها لمدة 20-25 دقيقة، مع التقليب مرة واحدة في منتصف المدة، حتى تصبح طرية ومحمرّة قليلًا.","في المقلاة نفسها، سخّن 1½ ملعقة صغيرة المتبقية من زيت الزيتون على حرارة متوسطة. أضف لحم البقر المفروم والفطر المفروم والفلفل الرومي الأحمر المقطع إلى مكعبات. اطهِ لمدة 8-10 دقائق مع تفتيت اللحم، حتى ينضج اللحم تمامًا وتصبح الخضار طرية.","أضف مسحوق الفلفل الحار والكمون والبابريكا المدخنة ومسحوق الثوم ومسحوق البصل و¼ ملعقة صغيرة المتبقية من الملح و¼ ملعقة صغيرة من الفلفل الأسود وقلّب. اطهِ لمدة 1-2 دقيقة حتى تفوح الرائحة. أضف صلصة الطماطم والماء واتركها تغلي ببطء. اتركها حتى تغلي ثم اخفض الحرارة واتركها على نار هادئة لمدة 5-7 دقائق، حتى يتقلص السائل. ارفعها عن النار.","بينما يغلي خليط اللحم على نار هادئة، سخّن أرز القرنبيط في مقلاة كبيرة غير لاصقة على حرارة متوسطة لمدة 3-4 دقائق، مع التحريك من حين لآخر حتى يسخن تمامًا. أضف الكزبرة الخضراء وعصير الليمون الأخضر واخلط. أبقِه دافئًا حتى وقت التقديم.","قسّم أرز القرنبيط بالتساوي بين أربعة أوعية. ضع فوق كل وعاء بالتساوي البطاطس المحمصة وخليط اللحم والفطر والفلفل وحبتي طماطم و¼ حبة أفوكادو مقطعة إلى شرائح."],[],[])))
O.append(R(6530550,
en=("Kid-Friendly Rainbow Fruit Platter","A quick, easy, and colorful recipe that anyone can make! Try it as breakfast, a snack, or even dessert.","25",None,
["8 oz vanilla Greek yogurt (100 calories)","1 tbsp chia seeds","1/8 tsp ground cinnamon","4 cups whole strawberries (hulled)","4 cups cantaloupe (cubed)","1 fresh pineapple (peeled, cored, and cubed (about 4 cups))","3 cups green grapes","4 cups blueberries","3 cups red grapes","3 cups blackberries"],
["Mix the yogurt and chia seeds. Refrigerate overnight. Mix in 1/8 tsp cinnamon.","On a very large platter, place the strawberries in the top row to form the top of a rainbow pattern.","Place the cantaloupe cubes as the second row below the strawberries. Continue this process with the pineapple, going through the blackberries, to make the rainbow pattern."],[],[]),
ar=("طبق فواكه قوس قزح مناسب للأطفال","وصفة سريعة وسهلة وملوّنة يستطيع أي شخص تحضيرها! جرّبها وجبة فطور أو وجبة خفيفة أو حتى حلوى.","25",None,
["8 أونصة زبادي يوناني بالفانيليا (100 سعرة حرارية)","1 ملعقة كبيرة بذور الشيا","⅛ ملعقة صغيرة قرفة مطحونة","4 كوب فراولة كاملة (منزوعة العنق)","4 كوب شمام (مقطع إلى مكعبات)","1 أناناس طازج (مقشر ومنزوع القلب ومقطع إلى مكعبات (حوالي 4 كوب))","3 كوب عنب أخضر","4 كوب توت أزرق","3 كوب عنب أحمر","3 كوب توت أسود"],
["اخلط الزبادي وبذور الشيا. ضعه في الثلاجة طوال الليل. أضف ⅛ ملعقة صغيرة من القرفة واخلط.","على طبق كبير جدًا، ضع الفراولة في الصف العلوي لتشكيل الجزء العلوي من نمط قوس قزح.","ضع مكعبات الشمام كصف ثانٍ أسفل الفراولة. تابع بالطريقة نفسها مع الأناناس وصولًا إلى التوت الأسود لإكمال نمط قوس قزح."],[],[])))
